import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import Specimen from "./Specimen.js";

describe("EntityCard.Specimen", () => {
  it("is one image named by its label, its kind in data-specimen", () => {
    render(
      <Specimen kind="block" label="The Button on the live stylesheet">
        <button type="button">Save</button>
      </Specimen>,
    );
    const image = screen.getByRole("img", {
      name: "The Button on the live stylesheet",
    });
    expect(image.getAttribute("data-specimen")).toBe("block");
    expect(image.className).toBe("ds specimen");
  });

  it("keeps its depiction inert", () => {
    const { container } = render(
      <Specimen kind="drawing" label="A drawing">
        <button type="button">Save</button>
      </Specimen>,
    );
    expect(container.querySelector(".depiction")?.hasAttribute("inert")).toBe(
      true,
    );
  });

  it("throws on an empty label", () => {
    expect(() =>
      render(
        <Specimen kind="swatch" label=" ">
          <span />
        </Specimen>,
      ),
    ).toThrow("EntityCard.Specimen needs a label that names it");
  });
});
